INSERT INTO "admin_permissions" ("key") VALUES ('releases.read'),('releases.review'),('releases.override'),('distribution.submit'),('distribution.retry'),('distribution.confirm_status'),('updates.review'),('takedowns.review'),('royalties.import'),('royalties.reconcile'),('wallets.adjust'),('payouts.review'),('payouts.approve'),('payouts.mark_paid'),('kyc.review'),('users.read'),('users.manage'),('services.manage'),('audit.read'),('system.manage') ON CONFLICT ("key") DO NOTHING;
INSERT INTO "admin_roles" ("key","name","updated_at") VALUES ('super_admin','Super admin',CURRENT_TIMESTAMP),('qc_reviewer','QC reviewer',CURRENT_TIMESTAMP),('distribution_operator','Distribution operator',CURRENT_TIMESTAMP),('finance_operator','Finance operator',CURRENT_TIMESTAMP),('payout_approver','Payout approver',CURRENT_TIMESTAMP),('support_agent','Support agent',CURRENT_TIMESTAMP),('rights_operator','Rights operator',CURRENT_TIMESTAMP),('read_only_auditor','Read-only auditor',CURRENT_TIMESTAMP) ON CONFLICT ("key") DO NOTHING;
INSERT INTO "admin_role_permissions" ("role_id","permission_id") SELECT r.id,p.id FROM "admin_roles" r CROSS JOIN "admin_permissions" p WHERE r.key='super_admin' ON CONFLICT DO NOTHING;
INSERT INTO "admin_memberships" ("user_id","role_id","updated_at") SELECT u.id,r.id,CURRENT_TIMESTAMP FROM "users" u CROSS JOIN "admin_roles" r WHERE u.role='ADMIN' AND r.key='super_admin' ON CONFLICT ("user_id") DO NOTHING;
INSERT INTO "admin_role_permissions" ("role_id","permission_id") SELECT r.id,p.id FROM "admin_roles" r JOIN "admin_permissions" p ON p.key IN ('releases.read','releases.review') WHERE r.key='qc_reviewer' ON CONFLICT DO NOTHING;
INSERT INTO "admin_role_permissions" ("role_id","permission_id") SELECT r.id,p.id FROM "admin_roles" r JOIN "admin_permissions" p ON p.key IN ('releases.read','distribution.submit','distribution.retry','distribution.confirm_status') WHERE r.key='distribution_operator' ON CONFLICT DO NOTHING;
INSERT INTO "admin_role_permissions" ("role_id","permission_id") SELECT r.id,p.id FROM "admin_roles" r JOIN "admin_permissions" p ON p.key IN ('royalties.import','royalties.reconcile','wallets.adjust','payouts.review') WHERE r.key='finance_operator' ON CONFLICT DO NOTHING;
INSERT INTO "admin_role_permissions" ("role_id","permission_id") SELECT r.id,p.id FROM "admin_roles" r JOIN "admin_permissions" p ON p.key IN ('payouts.review','payouts.approve','payouts.mark_paid','kyc.review') WHERE r.key='payout_approver' ON CONFLICT DO NOTHING;
INSERT INTO "admin_role_permissions" ("role_id","permission_id") SELECT r.id,p.id FROM "admin_roles" r JOIN "admin_permissions" p ON p.key IN ('releases.read','users.read') WHERE r.key='support_agent' ON CONFLICT DO NOTHING;
INSERT INTO "admin_role_permissions" ("role_id","permission_id") SELECT r.id,p.id FROM "admin_roles" r JOIN "admin_permissions" p ON p.key IN ('releases.read','updates.review','takedowns.review','services.manage') WHERE r.key='rights_operator' ON CONFLICT DO NOTHING;
INSERT INTO "admin_role_permissions" ("role_id","permission_id") SELECT r.id,p.id FROM "admin_roles" r JOIN "admin_permissions" p ON p.key IN ('releases.read','audit.read') WHERE r.key='read_only_auditor' ON CONFLICT DO NOTHING;
