CREATE TABLE "admin_roles" ("id" SERIAL NOT NULL, "key" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "admin_roles_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "admin_roles_key_key" ON "admin_roles"("key");
CREATE TABLE "admin_permissions" ("id" SERIAL NOT NULL, "key" TEXT NOT NULL, "description" TEXT, CONSTRAINT "admin_permissions_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "admin_permissions_key_key" ON "admin_permissions"("key");
CREATE TABLE "admin_role_permissions" ("role_id" INTEGER NOT NULL, "permission_id" INTEGER NOT NULL, CONSTRAINT "admin_role_permissions_pkey" PRIMARY KEY ("role_id", "permission_id"), CONSTRAINT "admin_role_permissions_role_id_fkey" FOREIGN KEY ("role_id") REFERENCES "admin_roles"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "admin_role_permissions_permission_id_fkey" FOREIGN KEY ("permission_id") REFERENCES "admin_permissions"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "admin_memberships" ("id" SERIAL NOT NULL, "user_id" INTEGER NOT NULL, "role_id" INTEGER NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "created_by" INTEGER, "revoked_at" TIMESTAMP(3), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "admin_memberships_pkey" PRIMARY KEY ("id"), CONSTRAINT "admin_memberships_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "admin_memberships_role_id_fkey" FOREIGN KEY ("role_id") REFERENCES "admin_roles"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "admin_memberships_user_id_key" ON "admin_memberships"("user_id");
CREATE INDEX "admin_memberships_role_id_active_idx" ON "admin_memberships"("role_id", "active");

